module.exports=`
(() => {
 const records = new Map(JSON.parse(sessionStorage.getItem('mock-firebase')||'[]',(_,v)=>v&&v._mockMillis?{toMillis:()=>v._mockMillis}:v));
 const persist=()=>sessionStorage.setItem('mock-firebase',JSON.stringify([...records],(_,v)=>v?.toMillis?{_mockMillis:v.toMillis()}:v));
 const user={uid:'browser-test',displayName:'Atleta de teste',email:'test@example.invalid',getIdToken:async()=> 'test-token',getIdTokenResult:async()=>({claims:{}})};
 const auth={currentUser:user,onAuthStateChanged(fn){setTimeout(()=>{fn(this.currentUser);if(this.currentUser&&window.FitStore?.uid===this.currentUser.uid&&!FitStore.get('fitapp_resources_academia')){const resources=[...new Set((window.dictionaryData||[]).flatMap(m=>m.executionProfile?.resources||[]))];FitStore.set('fitapp_resources_academia',JSON.stringify(resources));}},0);},async signOut(){this.currentUser=null;},async signInWithPopup(){}};
 function authFn(){return auth;} authFn.GoogleAuthProvider=class{};
 const makeDoc=(name,id)=>({id,collection:child=>collection(name+'/'+id+'/'+child),async get(){return{id,exists:records.has(name+'/'+id),data:()=>records.get(name+'/'+id)};},async set(value,options){records.set(name+'/'+id,options?.merge?{...records.get(name+'/'+id),...value}:value);persist();},async delete(){records.delete(name+'/'+id);persist();}});
 function collection(name){let conditions=[],maximum=Infinity,after=null,sort=null,direction='asc';return{doc:id=>makeDoc(name,id),where(k,op,v){conditions.push([k,op,v]);return this;},orderBy(k,d='asc'){sort=k;direction=d;return this;},limit(n){maximum=n;return this;},startAfter(doc){after=doc.id;return this;},async get(){let docs=[...records.entries()].filter(([key,value])=>key.startsWith(name+'/')&&!key.slice(name.length+1).includes('/')&&conditions.every(([k,op,v])=>op==='>='?(value[k]?.toMillis?.()||value[k])>=Number(v):value[k]===v)).map(([key,value])=>({id:key.slice(name.length+1),data:()=>value}));if(sort)docs.sort((a,b)=>{const av=a.data()[sort]?.toMillis?.()||a.data()[sort],bv=b.data()[sort]?.toMillis?.()||b.data()[sort];return(av<bv?-1:av>bv?1:a.id.localeCompare(b.id))*(direction==='desc'?-1:1);});if(after)docs=docs.slice(docs.findIndex(d=>d.id===after)+1);docs=docs.slice(0,maximum);return{empty:!docs.length,size:docs.length,docs,forEach:fn=>docs.forEach(fn)};}};}
 const db={collection,async runTransaction(fn){return fn({get:ref=>ref.get(),set:(ref,data,options)=>ref.set(data,options),delete:ref=>ref.delete()});}};
 function firestore(){return db;}firestore.FieldValue={serverTimestamp:()=>({toMillis:()=>Date.now()})};
 window.firebase={apps:[],initializeApp(){this.apps.push({});},auth:authFn,firestore};
})();`;
